from datetime import datetime

_DIGITS = "0123456789"
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _all_digits(s, n=None):
    """True if s is non-empty, all ASCII digits, and exactly n long (if n is given)."""
    if n is not None and len(s) != n:
        return False
    return len(s) > 0 and all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = raw.strip()
    start = s.find("<")
    if start != -1:
        end = s.find(">", start + 1)
        if end != -1:
            s = s[start + 1:end]
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = f"{local}@gmail.com"
    return s


def _is_valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    """Return the 10-digit phone, or "" if invalid."""
    s = raw.strip().lower()
    cuts = [p for p in (s.find("x"), s.find("ext"), s.find("#")) if p != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    s = raw.strip()
    # ZIP+4 such as "02139-4307": keep the part before the hyphen.
    if len(s) == 10 and s[5] == "-" and _all_digits(s[:5], 5) and _all_digits(s[6:], 4):
        s = s[:5]
    # Excel dropped the leading zero.
    if _all_digits(s, 4):
        s = "0" + s
    return s if _all_digits(s, 5) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _is_opted_out(raw):
    return raw.strip().lower() in ("y", "yes", "true", "1")


def _parse_tags(raw):
    parts = raw.replace(",", ";").split(";")
    return {p.strip().lower() for p in parts if p.strip()}


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _first_nonempty(ordered, kept, field):
    for i in ordered:
        if kept[i][field]:
            return kept[i][field]
    return ""


def dedupe_contacts(rows):
    # Step 1: normalize every row and drop rows with no valid email or phone.
    kept = []
    for row in rows:
        email_norm = _normalize_email(row["email"])
        email = email_norm if _is_valid_email(email_norm) else ""
        phone = _normalize_phone(row["phone"])
        if not email and not phone:
            continue
        source = row["source"].strip().lower()
        kept.append({
            "first_name": _normalize_name(row["first_name"]),
            "last_name": _normalize_name(row["last_name"]),
            "zip": _normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(row["tags"]),
            "opted_out": _is_opted_out(row["opted_out"]),
            "updated": _parse_updated(row["updated"]),
        })

    # Step 2: group rows with union-find. Each index in `kept` is the
    # row's position in the input, since dropped rows were skipped in order.
    parent = list(range(len(kept)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    # Matching rules: same valid email, or same valid phone plus same
    # non-empty last name (case-insensitive). Indexing by key and unioning
    # rows that share a key gives the same transitive grouping as pairwise
    # comparison, without the O(n^2) cost.
    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(kept):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        lname = r["last_name"].lower()
        if r["phone"] and lname:
            key = (r["phone"], lname)
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    # Groups are inserted in order of their earliest row, which gives the
    # required output order.
    groups = {}
    for i in range(len(kept)):
        groups.setdefault(find(i), []).append(i)

    # Step 3: build one output record per person.
    output = []
    for members in groups.values():
        # Preference order: manual source first, then most recent `updated`,
        # then earlier input position. Python's sort is stable, so the last
        # sort is the primary key.
        ordered = sorted(members)                                         # input order
        ordered.sort(key=lambda i: kept[i]["updated"], reverse=True)      # newest first
        ordered.sort(key=lambda i: not kept[i]["manual"])                 # manual first

        tags = set().union(*(kept[i]["tags"] for i in members))
        latest = max(kept[i]["updated"] for i in members)

        output.append({
            "first_name": _first_nonempty(ordered, kept, "first_name"),
            "last_name": _first_nonempty(ordered, kept, "last_name"),
            "zip": _first_nonempty(ordered, kept, "zip"),
            "email": _first_nonempty(ordered, kept, "email"),
            "phone": _first_nonempty(ordered, kept, "phone"),
            "source": _first_nonempty(ordered, kept, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(kept[i]["opted_out"] for i in members) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
```

Notes for the send:

- **Filter opt-outs before sending.** The function reports `opted_out` but does not remove anyone. Build the send list with `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N"]`.
- **Shared phone and last name can merge people.** Per rule 10, two different people with the same phone and last name are treated as one. Because `opted_out` is merged across a group, one opt-out can suppress a second person's email. Worth a spot check if the export has shared household or office lines.
- **Bad dates raise an error.** A malformed `updated` value raises `ValueError` rather than being silently guessed. I chose this so a bad export fails loudly before anything goes out. The data person may prefer a different fallback.
